mapper.select:
SELECT CUST_ID AS custId , CUST_NM AS custNm , BIZ_REG_NO AS bizRegNo , CEO_NM AS ceoNm , PIC_NM AS picNm , PIC_TEL AS picTel , PIC_EMAIL AS picEmail FROM TB_CUSTOMER WHERE 1=1
AND CUST_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY CUST_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
INSERT INTO TB_CUSTOMER (
    CUST_NM, BIZ_REG_NO, CEO_NM, PIC_NM, PIC_TEL, PIC_EMAIL, CUST_ADDR, CUST_REMARK
) VALUES (
    #{custNm}, #{bizRegNo}, #{ceoNm}, #{picNm}, #{picTel}, #{picEmail}, #{custAddr}, #{custRemark}
)

mapper.update:
UPDATE TB_CUSTOMER SET
      CUST_NM = #{custNm}
    , BIZ_REG_NO = #{bizRegNo}
    , CEO_NM = #{ceoNm}
    , PIC_NM = #{picNm}
    , PIC_TEL = #{picTel}
    , PIC_EMAIL = #{picEmail}
    , CUST_ADDR = #{custAddr}
    , CUST_REMARK = #{custRemark}
WHERE CUST_ID = #{custId}
